def solve(n1, n2, n3, n4, n5, n6, minutes):
    arr = [n1, n2, n3, n4, n5, n6]
    for _ in range(minutes):
        new_arr = list(arr)
        n = len(arr)
        for i in range(n):
            nxt = arr[(i + 1) % n]
            if arr[i] < nxt:
                new_arr[i] += 1
            elif arr[i] > nxt:
                new_arr[i] -= 1
        arr = new_arr
    return sum(arr)
